// server/longitudinal-user-model.js
//
// Longitudinal User Model Agent — Layer 5 (Memory) of the Arete AI Agent System.
//
// Runs weekly (Mondays 04:30 UTC, 30 min after the Journal Analysis Agent's
// cycle) and, for each user with enough signal, rebuilds a living philosophical
// portrait from ALL of their accumulated journal_analysis rows — not a summary
// of one week, but a portrait of who they are becoming over time. Theme
// persistence is computed programmatically; the prose portrait, delta, and
// growth edges are generated by Claude in a single call per user.
//
// The model is a living document — one row per user, overwritten each week
// (ON CONFLICT user_id). The prior state is snapshotted into
// longitudinal_model_history before each overwrite so the arc is preserved.
//
// Standalone script (its own Railway cron service). Mirrors the sibling agents:
// raw fetch to Anthropic, no SDKs. No retrieval, so OpenAI is not needed.
// Env: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, CLAUDE_API_KEY.

require('dotenv').config();
const { createClient } = require('@supabase/supabase-js');

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);
const CLAUDE_API_KEY = process.env.CLAUDE_API_KEY;

const DAY = 24 * 60 * 60 * 1000;
const DEFAULT_MODEL = 'claude-sonnet-4-6';

// Windows / thresholds (overridable via agent_config).
const DEFAULTS = {
  min_weeks_required: 4,          // users with fewer analysis weeks are skipped
  theme_persistence_threshold: 3, // weeks a theme must appear in to be "persistent"
  theme_persistence_window_weeks: 8, // recency window for persistence detection
  portrait_max_words: 500,
  model: DEFAULT_MODEL,
};

// Volume that counts as "fully consistent" for a single week, used to scale the
// 0-100 practice scores. A week with this many entries/conversations scores 100
// for that week; the score is the mean of the per-week ratios over the window.
const TARGET_ENTRIES_PER_WEEK = 4;
const TARGET_CONVOS_PER_WEEK = 3;

// Truncate a UUID for logs — we never print full user ids or content (privacy).
function shortId(id) {
  return (id || '').toString().slice(0, 8);
}

// Monday (UTC), as YYYY-MM-DD, for an arbitrary date — buckets activity by week
// the same way the other agents key their weekly rows.
function mondayOf(date) {
  const d = new Date(date);
  const day = d.getUTCDay(); // 0=Sun .. 6=Sat
  const diff = (day === 0 ? -6 : 1) - day;
  d.setUTCDate(d.getUTCDate() + diff);
  return d.toISOString().split('T')[0];
}

function mondayOfCurrentWeek() {
  return mondayOf(new Date());
}

// The Monday of each of the last `n` weeks (most recent last), as YYYY-MM-DD.
function recentWeekStarts(n) {
  const weeks = [];
  const thisMonday = new Date(mondayOfCurrentWeek() + 'T00:00:00Z');
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(thisMonday.getTime() - i * 7 * DAY);
    weeks.push(d.toISOString().split('T')[0]);
  }
  return weeks;
}

// --- Config ----------------------------------------------------------------

async function getAgentConfig() {
  const { data } = await supabase
    .from('agent_config')
    .select('config')
    .eq('agent_name', 'longitudinal-user-model')
    .maybeSingle();
  return { ...DEFAULTS, ...(data?.config || {}) };
}

// --- Eligibility ------------------------------------------------------------

// Users with at least `minWeeks` distinct analysis_week rows in journal_analysis.
// Returns [{ userId, weekCount }]. journal_analysis is one row per user per week
// (small), so tallying client-side is safe at current scale.
async function getEligibleUsers(minWeeks) {
  const { data, error } = await supabase
    .from('journal_analysis')
    .select('user_id, analysis_week')
    .order('analysis_week', { ascending: true });
  if (error) throw new Error(`eligible users: ${error.message}`);

  const weeksByUser = new Map();
  for (const row of data || []) {
    if (!row.user_id) continue;
    if (!weeksByUser.has(row.user_id)) weeksByUser.set(row.user_id, new Set());
    weeksByUser.get(row.user_id).add(String(row.analysis_week));
  }

  const eligible = [];
  const skipped = [];
  for (const [userId, weeks] of weeksByUser.entries()) {
    if (weeks.size >= minWeeks) eligible.push({ userId, weekCount: weeks.size });
    else skipped.push({ userId, weekCount: weeks.size });
  }
  return { eligible, skipped };
}

// --- Data gathering ---------------------------------------------------------

// All journal_analysis rows for a user, oldest → newest.
async function getAnalysisHistory(userId) {
  const { data } = await supabase
    .from('journal_analysis')
    .select('analysis_week, themes, journal_only_themes, cabinet_only_themes, dominant_theme, distress_flagged')
    .eq('user_id', userId)
    .order('analysis_week', { ascending: true });
  return data || [];
}

async function getRecentJournalEntries(userId, windowWeeks) {
  const since = new Date(Date.now() - windowWeeks * 7 * DAY).toISOString();
  const { data } = await supabase
    .from('journal_entries')
    .select('type, created_at')
    .eq('user_id', userId)
    .gte('created_at', since);
  return data || [];
}

async function getRecentCabinetConversations(userId, windowWeeks) {
  const since = new Date(Date.now() - windowWeeks * 7 * DAY).toISOString();
  const { data } = await supabase
    .from('cabinet_conversations')
    .select('counselor_slugs, messages, created_at, updated_at')
    .eq('user_id', userId)
    .gte('updated_at', since);
  return data || [];
}

async function getPriorModel(userId) {
  const { data } = await supabase
    .from('user_longitudinal_models')
    .select('*')
    .eq('user_id', userId)
    .maybeSingle();
  return data || null;
}

// --- Theme extraction + persistence ----------------------------------------

// Pull the set of theme names from a journal_analysis row. `themes` is a jsonb
// array of { theme, count, sources, weeksSeen } (see journal-analysis-agent).
// Returns display names; callers normalize for comparison.
function themeNamesFromRow(row) {
  const out = [];
  const arr = Array.isArray(row.themes) ? row.themes : [];
  for (const t of arr) {
    const name = (t && (typeof t === 'string' ? t : t.theme)) || '';
    const trimmed = String(name).trim();
    if (trimmed) out.push(trimmed);
  }
  return out;
}

const norm = (s) => String(s || '').trim().toLowerCase();

// Classify themes into persistent / emerging / fading from the analysis history.
//   persistent — appears in `threshold`+ of the last `window` weeks
//   emerging   — appears in the most recent 1-2 weeks but in no earlier week
//   fading     — appeared in 3+ weeks prior to the last 3, and is absent in the
//                last 3 weeks
// Also returns growth-edge candidates: persistent themes still present in the
// most recent week (recurring and still open — the user keeps returning to them).
function classifyThemes(history, threshold, windowWeeks) {
  // Per-week theme sets (normalized), oldest → newest, plus a display-name map.
  const display = new Map(); // norm -> nicest display name seen
  const weekSets = history.map((row) => {
    const set = new Set();
    for (const name of themeNamesFromRow(row)) {
      const key = norm(name);
      if (!key) continue;
      set.add(key);
      if (!display.has(key)) display.set(key, name);
    }
    return set;
  });

  const nice = (key) => display.get(key) || key;
  const countIn = (sets, key) => sets.reduce((n, s) => n + (s.has(key) ? 1 : 0), 0);

  const recent = weekSets.slice(-windowWeeks);
  const allKeys = new Set();
  for (const s of weekSets) for (const k of s) allKeys.add(k);

  const last1 = weekSets.slice(-1);
  const last2 = weekSets.slice(-2);
  const last3 = weekSets.slice(-3);
  const beforeLast2 = weekSets.slice(0, -2);
  const beforeLast3 = weekSets.slice(0, -3);
  const latest = weekSets[weekSets.length - 1] || new Set();

  const persistent = [];
  const emerging = [];
  const fading = [];
  const growthCandidates = [];

  for (const key of allKeys) {
    const inRecent = countIn(recent, key);
    const inLast2 = countIn(last2, key);
    const inLast3 = countIn(last3, key);
    const inBeforeLast2 = countIn(beforeLast2, key);
    const inBeforeLast3 = countIn(beforeLast3, key);

    const isPersistent = inRecent >= threshold;
    if (isPersistent) persistent.push({ theme: nice(key), weeks_seen: inRecent });

    // Emerging: showed up only in the last 1-2 weeks, never before.
    if (inLast2 >= 1 && inBeforeLast2 === 0) {
      emerging.push({ theme: nice(key), weeks_seen: inLast2 });
    }

    // Fading: was a recurring theme earlier (3+ prior weeks) but gone the last 3.
    if (inBeforeLast3 >= 3 && inLast3 === 0) {
      fading.push({ theme: nice(key), prior_weeks_seen: inBeforeLast3 });
    }

    // Growth-edge candidate: persistent AND still present this week — a question
    // the user carries and has not put down.
    if (isPersistent && latest.has(key)) {
      growthCandidates.push(nice(key));
    }
  }

  // A theme that has gone quiet the last 3 weeks is fading, not persistent —
  // fading wins the tie so the portrait doesn't call the same theme both.
  const fadingKeys = new Set(fading.map((f) => norm(f.theme)));
  const persistentFinal = persistent.filter((p) => !fadingKeys.has(norm(p.theme)));

  persistentFinal.sort((a, b) => b.weeks_seen - a.weeks_seen);
  emerging.sort((a, b) => b.weeks_seen - a.weeks_seen);
  fading.sort((a, b) => b.prior_weeks_seen - a.prior_weeks_seen);

  return { persistent: persistentFinal, emerging, fading, growthCandidates };
}

// --- Practice patterns ------------------------------------------------------

// Mean of per-week ratios (min(count, target)/target) over the window, ×100.
// Rewards both showing up (many active weeks) and volume, capped so a single
// prolific week can't peg the score.
function weeklyRatioScore(itemsByWeek, weekStarts, target) {
  if (!weekStarts.length) return 0;
  let sum = 0;
  for (const wk of weekStarts) {
    const count = itemsByWeek.get(wk) || 0;
    sum += Math.min(count, target) / target;
  }
  return Math.round((sum / weekStarts.length) * 100 * 100) / 100; // 2dp
}

function bucketByWeek(rows, dateField) {
  const map = new Map();
  for (const r of rows) {
    const wk = mondayOf(r[dateField] || r.created_at);
    map.set(wk, (map.get(wk) || 0) + 1);
  }
  return map;
}

function journalConsistency(entries, weekStarts) {
  const byWeek = bucketByWeek(entries, 'created_at');
  return weeklyRatioScore(byWeek, weekStarts, TARGET_ENTRIES_PER_WEEK);
}

function cabinetEngagement(convos, weekStarts) {
  const byWeek = bucketByWeek(convos, 'updated_at');
  return weeklyRatioScore(byWeek, weekStarts, TARGET_CONVOS_PER_WEEK);
}

// Distribution of journal entry types over the window → [{ type, count, pct }].
function entryTypeDistribution(entries) {
  const counts = new Map();
  for (const e of entries) {
    const type = (e.type || 'unspecified').trim() || 'unspecified';
    counts.set(type, (counts.get(type) || 0) + 1);
  }
  const total = entries.length || 1;
  return [...counts.entries()]
    .map(([type, count]) => ({ type, count, pct: Math.round((count / total) * 100) }))
    .sort((a, b) => b.count - a.count);
}

// Which counselors this user leans on, across their recent Cabinet threads.
// Prefer the conversation-level counselor_slugs; fall back to per-message
// counselorName/counselorId when slugs are absent (older rows). → [{ counselor, count }].
function counselorAffinity(convos) {
  const counts = new Map();
  const bump = (name) => {
    const key = String(name || '').trim();
    if (!key) return;
    counts.set(key, (counts.get(key) || 0) + 1);
  };

  for (const c of convos) {
    const slugs = Array.isArray(c.counselor_slugs) ? c.counselor_slugs : [];
    if (slugs.length) {
      for (const s of slugs) bump(s);
      continue;
    }
    const messages = Array.isArray(c.messages) ? c.messages : [];
    const seen = new Set();
    for (const m of messages) {
      if (m && m.role === 'assistant') {
        const who = m.counselorName || m.counselorId;
        if (who && !seen.has(who)) { seen.add(who); bump(who); }
      }
    }
  }

  return [...counts.entries()]
    .map(([counselor, count]) => ({ counselor, count }))
    .sort((a, b) => b.count - a.count);
}

// --- Claude generation ------------------------------------------------------

const SYSTEM_PROMPT = `You are the memory layer of the Arete philosophical platform. Your job is to build a living portrait of a user's philosophical journey — not from a single week, but from everything they have written and explored over time.

You write with care and precision. This portrait is private — the user may eventually see it, and the Cabinet counselors will use it to know this person more deeply over time.

Your tone is warm, specific, and philosophically serious. You do not pathologize. You do not project. You stay close to what the data actually shows. Where you are uncertain, you say so.

The philosophical portrait is not a summary of their journal entries. It is a portrait of who they are becoming — the recurring questions they carry, the edges where they are growing, the patterns that persist beneath the surface of any single week.

Every claim must be grounded in the data provided. Do not invent themes or patterns not present in the input.`;

function buildUserMessage(input, maxWords) {
  const list = (arr) => (arr && arr.length ? arr.join(', ') : 'none');
  const themeList = (arr) => (arr && arr.length ? arr.map((t) => t.theme).join(', ') : 'none');
  const dist = (arr) => (arr && arr.length ? arr.map((d) => `${d.type} (${d.pct}%)`).join(', ') : 'none');
  const counselors = (arr) => (arr && arr.length ? arr.slice(0, 3).map((c) => c.counselor).join(', ') : 'none');

  return `User data:
- Weeks analyzed: ${input.weeksAnalyzed}
- Persistent themes: ${themeList(input.persistent)}
- Emerging themes: ${themeList(input.emerging)}
- Fading themes: ${themeList(input.fading)}
- Growth edges (themes appearing repeatedly unresolved): ${list(input.growthCandidates)}
- Journal consistency score: ${input.journalConsistency}
- Cabinet engagement score: ${input.cabinetEngagement}
- Preferred entry types: ${dist(input.preferredEntryTypes)}
- Counselor affinity: ${counselors(input.counselorAffinity)}
- Prior portrait (if exists): ${input.priorPortrait || 'null'}
- Prior delta summary (if exists): ${input.priorDelta || 'null'}

Produce:
1. dominant_philosophical_orientation (one of: stoic, contemplative, pragmatic, existentialist, virtue-ethics, mixed — infer from theme patterns)
2. emotional_tone_baseline (one of: reflective, urgent, struggling, expansive, grounded, searching)
3. self_disclosure_depth (one of: surface, moderate, deep)
4. philosophical_portrait (300-${maxWords} words, prose, second person — "You return again and again to...")
5. delta_summary (2-3 sentences: what shifted meaningfully this week compared to the prior model — or "First model generated" if no prior exists)
6. growth_edges (array of 2-4 specific, named edges — e.g. "The gap between knowing the dichotomy of control and living it under pressure")

Respond ONLY with valid JSON:
{
  "dominant_philosophical_orientation": "string",
  "emotional_tone_baseline": "string",
  "self_disclosure_depth": "string",
  "philosophical_portrait": "string",
  "delta_summary": "string",
  "growth_edges": ["string", "string"]
}`;
}

async function callClaude(model, userMessage) {
  const res = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': CLAUDE_API_KEY,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: model || DEFAULT_MODEL,
      max_tokens: 2000,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: userMessage }],
    }),
  });
  if (!res.ok) throw new Error(`Claude API ${res.status}: ${await res.text()}`);
  const json = await res.json();
  const block = (json.content || []).find((b) => b.type === 'text');
  const raw = block ? block.text : '';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  return JSON.parse(cleaned);
}

// --- Per-user processing ----------------------------------------------------

async function buildModelForUser(userId, config) {
  const startTime = Date.now();
  const windowWeeks = config.theme_persistence_window_weeks;
  const threshold = config.theme_persistence_threshold;
  const weekStarts = recentWeekStarts(windowWeeks);

  const [history, entries, convos, priorModel] = await Promise.all([
    getAnalysisHistory(userId),
    getRecentJournalEntries(userId, windowWeeks),
    getRecentCabinetConversations(userId, windowWeeks),
    getPriorModel(userId),
  ]);

  const weeksAnalyzed = new Set(history.map((r) => String(r.analysis_week))).size;

  const { persistent, emerging, fading, growthCandidates } = classifyThemes(history, threshold, windowWeeks);
  const journalConsistencyScore = journalConsistency(entries, weekStarts);
  const cabinetEngagementScore = cabinetEngagement(convos, weekStarts);
  const preferredEntryTypes = entryTypeDistribution(entries);
  const affinity = counselorAffinity(convos);

  const generated = await callClaude(config.model, buildUserMessage({
    weeksAnalyzed,
    persistent,
    emerging,
    fading,
    growthCandidates,
    journalConsistency: journalConsistencyScore,
    cabinetEngagement: cabinetEngagementScore,
    preferredEntryTypes,
    counselorAffinity: affinity,
    priorPortrait: priorModel?.philosophical_portrait || null,
    priorDelta: priorModel?.delta_summary || null,
  }, config.portrait_max_words));

  const growthEdges = Array.isArray(generated.growth_edges) ? generated.growth_edges : [];
  const now = new Date().toISOString();

  // Snapshot the prior model before we overwrite it, preserving the arc.
  if (priorModel) {
    await supabase.from('longitudinal_model_history').insert({
      user_id: userId,
      snapshot_date: mondayOfCurrentWeek(),
      model_snapshot: priorModel,
      delta_summary: priorModel.delta_summary || null,
    });
  }

  // weeks_analyzed reflects the real count of distinct analysis weeks (weeks of
  // signal), not a run counter — that keeps it idempotent on re-runs and makes
  // the downstream "part of the platform for N weeks" line accurate.
  const row = {
    user_id: userId,
    persistent_themes: persistent,
    emerging_themes: emerging,
    fading_themes: fading,
    growth_edges: growthEdges,
    journal_consistency_score: journalConsistencyScore,
    cabinet_engagement_score: cabinetEngagementScore,
    preferred_entry_types: preferredEntryTypes,
    counselor_affinity: affinity,
    dominant_philosophical_orientation: generated.dominant_philosophical_orientation || null,
    emotional_tone_baseline: generated.emotional_tone_baseline || null,
    self_disclosure_depth: generated.self_disclosure_depth || null,
    philosophical_portrait: generated.philosophical_portrait || null,
    portrait_updated_at: now,
    delta_summary: generated.delta_summary || null,
    weeks_analyzed: weeksAnalyzed,
    first_analyzed_at: priorModel?.first_analyzed_at || now,
    last_analyzed_at: now,
    model_used: config.model || DEFAULT_MODEL,
    generation_duration_ms: Date.now() - startTime,
  };

  const { error } = await supabase
    .from('user_longitudinal_models')
    .upsert(row, { onConflict: 'user_id' });
  if (error) throw new Error(`upsert model: ${error.message}`);

  return {
    isUpdate: !!priorModel,
    weeksAnalyzed,
    persistent,
    emerging,
    deltaSummary: generated.delta_summary || '',
  };
}

// --- Main -------------------------------------------------------------------

async function runLongitudinalUserModel() {
  const startAll = Date.now();
  console.log('[longitudinal-user-model] Monday 04:30 UTC run started');

  if (!process.env.SUPABASE_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set — aborting.');
    process.exit(1);
  }
  if (!CLAUDE_API_KEY) {
    console.error('CLAUDE_API_KEY not set — aborting.');
    process.exit(1);
  }

  const config = await getAgentConfig();
  if (config.enabled === false) {
    console.log('[longitudinal-user-model] Disabled in config. Exiting.');
    return { disabled: true };
  }

  const { eligible, skipped } = await getEligibleUsers(config.min_weeks_required);
  console.log(`[longitudinal-user-model] Eligible users: ${eligible.length} | Skipped (insufficient data): ${skipped.length}`);

  let updated = 0;
  let failures = 0;

  for (const { userId } of eligible) {
    try {
      const result = await buildModelForUser(userId, config);
      updated++;
      if (result.isUpdate) {
        const delta = (result.deltaSummary || '').slice(0, 80);
        console.log(`[longitudinal-user-model] User ${shortId(userId)}: portrait updated | weeks: ${result.weeksAnalyzed} | delta: ${delta}`);
      } else {
        const themes = result.persistent.slice(0, 3).map((t) => t.theme).join(', ') || '—';
        console.log(`[longitudinal-user-model] User ${shortId(userId)}: portrait generated | weeks: ${result.weeksAnalyzed} | themes: ${themes}`);
      }
      await new Promise((r) => setTimeout(r, 500)); // gentle rate limit
    } catch (err) {
      failures++;
      console.error(`[longitudinal-user-model] User ${shortId(userId)}: FAILED — ${err.message}`);
    }
  }

  const secs = ((Date.now() - startAll) / 1000).toFixed(0);
  console.log(`[longitudinal-user-model] Completed in ${secs}s | ${updated} models updated | ${failures} failures`);
  return { eligible: eligible.length, skipped: skipped.length, updated, failures };
}

module.exports = {
  mondayOf,
  recentWeekStarts,
  getAgentConfig,
  getEligibleUsers,
  classifyThemes,
  journalConsistency,
  cabinetEngagement,
  entryTypeDistribution,
  counselorAffinity,
  buildModelForUser,
  runLongitudinalUserModel,
};

if (require.main === module) {
  runLongitudinalUserModel().catch((err) => {
    console.error('Fatal error:', err);
    process.exit(1);
  });
}
